from jsonb_to_recordset($q$[{"id": 11247, "materia": "port", "nivel": 0, "enunciado": "Complete: \"Ontem, nós ____ ao cinema depois da prova.\"", "opcoes": ["fomos", "foram", "fui", "iremos"], "explicacao": "Sujeito \"nós\" e tempo passado: \"fomos\"."}, {"id": 11248, "materia": "port", "nivel": 0, "enunciado": "O plural de \"anel\" é:", "opcoes": ["anéis", "anels", "aneles", "anéus"], "explicacao": "Palavras terminadas em -el trocam o -l por -is."}, {"id": 11249, "materia": "port", "nivel": 0, "enunciado": "O masculino de \"madrinha\" é:", "opcoes": ["padrinho", "madrinho", "padrasto", "compadre"], "explicacao": "Madrinha e padrinho."}, {"id": 11250, "materia": "port", "nivel": 0, "enunciado": "O diminutivo de \"casa\" é:", "opcoes": ["casinha", "casarão", "casona", "caseiro"], "explicacao": "O sufixo -inha forma o diminutivo."}, {"id": 11251, "materia": "port", "nivel": 0, "enunciado": "O aumentativo de \"cão\" é:", "opcoes": ["canzarrão", "cãozinho", "canil", "cachorrinho"], "explicacao": "Cão, canzarrão (ou cachorrão)."}, {"id": 11252, "materia": "port", "nivel": 0, "enunciado": "Assinale a palavra que é um verbo:", "opcoes": ["correr", "bonito", "mesa", "rapidamente"], "explicacao": "Verbo indica ação, estado ou fenômeno."}, {"id": 11253, "materia": "port", "nivel": 0, "enunciado": "O antônimo de \"comprar\" é:", "opcoes": ["vender", "adquirir", "pagar", "trocar"], "explicacao": "Antônimo é a palavra de sentido contrário."}, {"id": 11254, "materia": "port", "nivel": 1, "enunciado": "Em \"Amanhã eu estudarei a matéria toda\", o verbo está no:", "opcoes": ["Futuro do presente", "Pretérito perfeito", "Presente", "Futuro do pretérito"], "explicacao": "Estudarei indica ação futura certa."}, {"id": 11255, "materia": "port", "nivel": 1, "enunciado": "Um sinônimo de \"efêmero\" é:", "opcoes": ["passageiro", "eterno", "pesado", "antigo"], "explicacao": "Efêmero é o que dura pouco."}, {"id": 11256, "materia": "port", "nivel": 1, "enunciado": "A separação silábica correta de \"pássaro\" é:", "opcoes": ["pás-sa-ro", "pá-ssa-ro", "páss-a-ro", "p-ás-sa-ro"], "explicacao": "Os dígrafos ss e rr se separam."}, {"id": 11257, "materia": "port", "nivel": 1, "enunciado": "Em \"Comprei três livros para estudar\", a palavra \"três\" é:", "opcoes": ["Numeral", "Adjetivo", "Advérbio", "Pronome"], "explicacao": "Indica quantidade exata."}, {"id": 11258, "materia": "port", "nivel": 1, "enunciado": "Em \"Os alunos estudiosos foram aprovados\", a palavra \"estudiosos\" é:", "opcoes": ["Adjetivo", "Advérbio", "Verbo", "Pronome"], "explicacao": "Qualifica o substantivo \"alunos\"."}, {"id": 11259, "materia": "port", "nivel": 1, "enunciado": "O plural de \"troféu\" é:", "opcoes": ["troféus", "troféis", "troféues", "troféuses"], "explicacao": "Palavras terminadas em -éu fazem o plural com -s."}, {"id": 11260, "materia": "port", "nivel": 1, "enunciado": "Assinale a palavra que tem dígrafo:", "opcoes": ["chuva", "prato", "blusa", "flor"], "explicacao": "Em \"chuva\", as letras ch representam um só som."}, {"id": 11261, "materia": "port", "nivel": 2, "enunciado": "Complete: \"Moro ___ cinco quadras do fórum.\"", "opcoes": ["a", "há", "à", "á"], "explicacao": "\"A\" também indica distância."}, {"id": 11262, "materia": "port", "nivel": 2, "enunciado": "Complete: \"Comprei o tênis na ____ de esportes da loja.\"", "opcoes": ["seção", "sessão", "cessão", "secção"], "explicacao": "Seção é divisão, setor. Secção é variante aceita, mas aqui a forma usual é seção."}, {"id": 11263, "materia": "port", "nivel": 2, "enunciado": "Assinale a frase com o uso correto de \"porquê\":", "opcoes": ["Não entendi o porquê da demora.", "Porquê você faltou?", "Ele saiu porquê estava cansado.", "Faltou, mas não disse por quê motivo."], "explicacao": "\"Porquê\" é substantivo e vem acompanhado de artigo."}, {"id": 11264, "materia": "port", "nivel": 2, "enunciado": "Complete: \"Havia ____ pessoas na fila do concurso.\"", "opcoes": ["bastantes", "bastante", "bastanto", "bastanta"], "explicacao": "\"Bastante\" antes de substantivo é adjetivo e concorda: bastantes pessoas."}, {"id": 11265, "materia": "port", "nivel": 2, "enunciado": "Complete: \"A janela estava ____ aberta.\"", "opcoes": ["meio", "meia", "meios", "meias"], "explicacao": "\"Meio\" como advérbio (um pouco) é invariável."}, {"id": 11266, "materia": "port", "nivel": 2, "enunciado": "Complete: \"Seguem ____ os documentos pedidos.\"", "opcoes": ["anexos", "anexo", "anexa", "anexas"], "explicacao": "\"Anexo\" é adjetivo e concorda com \"documentos\"."}, {"id": 11267, "materia": "port", "nivel": 2, "enunciado": "Complete: \"Nas férias, vou ___ Bahia.\"", "opcoes": ["à", "a", "há", "ah"], "explicacao": "Quem vai a algum lugar e volta \"da\" Bahia usa crase."}, {"id": 11268, "materia": "port", "nivel": 3, "enunciado": "Complete: \"Refiro-me ___ candidatas aprovadas.\"", "opcoes": ["às", "as", "às mesmas", "há"], "explicacao": "Referir-se a + as candidatas = às."}, {"id": 11269, "materia": "port", "nivel": 3, "enunciado": "Assinale a frase de acordo com a norma-padrão:", "opcoes": ["Esqueci-me do nome dele.", "Esqueci-me o nome dele.", "Esqueci do nome dele, me.", "Me esqueci o nome dele."], "explicacao": "Esquecer-se de algo (pronominal com preposição) ou esquecer algo (sem preposição)."}, {"id": 11270, "materia": "port", "nivel": 3, "enunciado": "Na norma-padrão, assinale a frase correta:", "opcoes": ["Ontem assisti ao jogo da seleção.", "Ontem assisti o jogo da seleção.", "Ontem assisti no jogo da seleção.", "Ontem assisti do jogo da seleção."], "explicacao": "No sentido de ver, \"assistir\" pede a preposição \"a\"."}, {"id": 11271, "materia": "port", "nivel": 3, "enunciado": "Complete: \"Vossa Excelência ____ cansado hoje.\"", "opcoes": ["está", "estais", "estás", "estou"], "explicacao": "Pronomes de tratamento levam o verbo à 3ª pessoa."}, {"id": 11272, "materia": "port", "nivel": 3, "enunciado": "Assinale a frase com colocação pronominal correta (norma-padrão):", "opcoes": ["Entregar-te-ei o livro amanhã.", "Entregarei-te o livro amanhã.", "Te entregarei o livro amanhã.", "Entregar-ei-te o livro amanhã."], "explicacao": "Com o futuro do presente, sem palavra atrativa, usa-se a mesóclise."}, {"id": 11273, "materia": "port", "nivel": 3, "enunciado": "Assinale a frase correta quanto à voz passiva sintética:", "opcoes": ["Vendem-se casas na praia.", "Vende-se casas na praia.", "Vendem-se casa na praia.", "Vende-se as casas na praia."], "explicacao": "O verbo concorda com o sujeito paciente \"casas\"."}, {"id": 11274, "materia": "port", "nivel": 3, "enunciado": "Assinale a frase em que a vírgula isola corretamente o vocativo:", "opcoes": ["Maria, venha ao balcão.", "Maria venha, ao balcão.", "Maria venha ao, balcão.", "Maria venha ao balcão,"], "explicacao": "O vocativo é sempre isolado por vírgula."}, {"id": 11275, "materia": "port", "nivel": 4, "enunciado": "Em \"Os candidatos, que estudaram, foram aprovados\", entende-se que:", "opcoes": ["Todos estudaram e foram aprovados", "Só parte dos candidatos estudou", "Ninguém foi aprovado", "Só os que não estudaram foram aprovados"], "explicacao": "A oração adjetiva explicativa (entre vírgulas) se refere a todos."}, {"id": 11276, "materia": "port", "nivel": 4, "enunciado": "Em \"Tenho necessidade de descanso\", o termo \"de descanso\" é:", "opcoes": ["Complemento nominal", "Objeto indireto", "Adjunto adverbial", "Agente da passiva"], "explicacao": "Completa o sentido do substantivo \"necessidade\"."}, {"id": 11277, "materia": "port", "nivel": 4, "enunciado": "Em \"O livro foi escrito por Machado de Assis\", o termo \"por Machado de Assis\" é:", "opcoes": ["Agente da passiva", "Objeto direto", "Sujeito", "Complemento nominal"], "explicacao": "Indica quem pratica a ação na voz passiva."}, {"id": 11278, "materia": "port", "nivel": 4, "enunciado": "Em \"O tempo é um rio que não volta\", há:", "opcoes": ["Metáfora", "Pleonasmo", "Hipérbole", "Eufemismo"], "explicacao": "Comparação implícita, sem o termo comparativo."}, {"id": 11279, "materia": "port", "nivel": 4, "enunciado": "Em \"Seu avô foi desta para melhor\", no sentido de morrer, há:", "opcoes": ["Eufemismo", "Hipérbole", "Pleonasmo", "Antítese"], "explicacao": "Suaviza uma ideia desagradável."}, {"id": 11280, "materia": "port", "nivel": 4, "enunciado": "A expressão \"subir para cima\" é exemplo de:", "opcoes": ["Pleonasmo vicioso", "Metáfora", "Catacrese", "Prosopopeia"], "explicacao": "Repetição desnecessária de ideia."}, {"id": 11281, "materia": "port", "nivel": 4, "enunciado": "Assinale a oração com sujeito oculto (desinencial):", "opcoes": ["Chegamos cedo ao trabalho.", "Choveu muito ontem.", "Alguém ligou para você.", "Os fiscais chegaram cedo hoje."], "explicacao": "O sujeito \"nós\" é identificado pela terminação do verbo."}, {"id": 11282, "materia": "rl", "nivel": 0, "enunciado": "Se hoje é terça-feira, depois de amanhã será:", "opcoes": ["Quinta-feira", "Quarta-feira", "Sexta-feira", "Segunda-feira"], "explicacao": "Terça + 2 dias = quinta."}, {"id": 11283, "materia": "rl", "nivel": 0, "enunciado": "O dobro de 35 é:", "opcoes": ["70", "65", "53", "75"], "explicacao": "35 × 2 = 70."}, {"id": 11284, "materia": "rl", "nivel": 0, "enunciado": "Uma reunião começou às 9h40 e durou 50 minutos. Ela terminou às:", "opcoes": ["10h30", "10h20", "10h40", "9h90"], "explicacao": "9h40 + 20 min = 10h; mais 30 min = 10h30."}, {"id": 11285, "materia": "rl", "nivel": 0, "enunciado": "João tinha 5 balas, ganhou 7 e deu 3 ao irmão. Com quantas ficou?", "opcoes": ["9", "15", "12", "5"], "explicacao": "5 + 7 − 3 = 9."}, {"id": 11286, "materia": "rl", "nivel": 0, "enunciado": "Uma caixa tem 6 ovos. Quantos ovos há em 4 caixas?", "opcoes": ["24", "10", "20", "18"], "explicacao": "6 × 4 = 24."}, {"id": 11287, "materia": "rl", "nivel": 1, "enunciado": "Na sequência 1, 4, 9, 16, ..., o próximo número é:", "opcoes": ["25", "20", "24", "32"], "explicacao": "São os quadrados: 1², 2², 3², 4², 5²."}, {"id": 11288, "materia": "rl", "nivel": 1, "enunciado": "Um livro de R$ 40 está com 25% de desconto. Ele sai por:", "opcoes": ["R$ 30", "R$ 35", "R$ 15", "R$ 25"], "explicacao": "25% de 40 = 10; 40 − 10 = 30."}, {"id": 11289, "materia": "rl", "nivel": 1, "enunciado": "Paulo é mais velho que Rui e mais novo que Sara. Quem é o mais velho?", "opcoes": ["Sara", "Paulo", "Rui", "Não dá para saber"], "explicacao": "A ordem é Sara, Paulo, Rui."}, {"id": 11290, "materia": "rl", "nivel": 1, "enunciado": "Um relógio marca 3h15. O ponteiro das horas está:", "opcoes": ["Entre o 3 e o 4", "Exatamente no 3", "Exatamente no 4", "Entre o 2 e o 3"], "explicacao": "Passados 15 minutos, o ponteiro das horas avança um quarto do caminho até o 4."}, {"id": 11291, "materia": "rl", "nivel": 1, "enunciado": "Comprei 3 cadernos de R$ 12 cada e paguei com R$ 50. O troco foi de:", "opcoes": ["R$ 14", "R$ 36", "R$ 12", "R$ 24"], "explicacao": "3 × 12 = 36; 50 − 36 = 14."}, {"id": 11292, "materia": "rl", "nivel": 2, "enunciado": "A negação de \"Nenhum aluno faltou\" é:", "opcoes": ["Algum aluno faltou", "Todos os alunos faltaram", "Nenhum aluno veio", "Todo aluno veio"], "explicacao": "A negação de \"nenhum\" é \"algum\"."}, {"id": 11293, "materia": "rl", "nivel": 2, "enunciado": "A negação de \"Ana é alta e Bia é loira\" é:", "opcoes": ["Ana não é alta ou Bia não é loira", "Ana não é alta e Bia também não é loira", "Ana é baixa e Bia é morena", "Ana é alta ou Bia é loira"], "explicacao": "Lei de De Morgan: ~(p ∧ q) = ~p ∨ ~q."}, {"id": 11294, "materia": "rl", "nivel": 2, "enunciado": "Três pedreiros constroem um muro em 6 dias. Seis pedreiros, no mesmo ritmo, constroem em:", "opcoes": ["3 dias", "12 dias", "6 dias", "2 dias"], "explicacao": "Grandezas inversamente proporcionais: o dobro de pessoas, metade do tempo."}, {"id": 11295, "materia": "rl", "nivel": 2, "enunciado": "Com os algarismos 1, 2 e 3, sem repetir, quantos números de dois algarismos podem ser formados?", "opcoes": ["6", "9", "3", "5"], "explicacao": "3 × 2 = 6."}, {"id": 11296, "materia": "rl", "nivel": 2, "enunciado": "A razão entre 15 e 60 é:", "opcoes": ["1/4", "4", "1/3", "3/4"], "explicacao": "15 ÷ 60 = 1/4."}, {"id": 11297, "materia": "rl", "nivel": 3, "enunciado": "A frase \"Se chover, levo guarda-chuva\" é falsa em qual situação?", "opcoes": ["Choveu e não levei guarda-chuva", "Não choveu e levei guarda-chuva", "Não choveu e não levei", "Choveu e levei guarda-chuva"], "explicacao": "A condicional só é falsa com antecedente verdadeiro e consequente falso."}, {"id": 11298, "materia": "rl", "nivel": 3, "enunciado": "A proposição \"Ou chove, ou faz sol\" (disjunção exclusiva) é verdadeira quando:", "opcoes": ["Exatamente uma das partes é verdadeira", "As duas partes são verdadeiras", "As duas partes são falsas", "Sempre, qualquer que seja o valor das partes"], "explicacao": "No \"ou... ou\", as duas não podem ser verdadeiras juntas."}, {"id": 11299, "materia": "rl", "nivel": 3, "enunciado": "Numa turma de 30 alunos, 18 gostam de futebol, 15 de vôlei e 5 de nenhum dos dois. Quantos gostam dos dois?", "opcoes": ["8", "3", "10", "5"], "explicacao": "25 gostam de algum: 18 + 15 − x = 25, então x = 8."}, {"id": 11300, "materia": "rl", "nivel": 3, "enunciado": "Na progressão geométrica 2, 6, 18, ..., o quinto termo é:", "opcoes": ["162", "54", "108", "486"], "explicacao": "Razão 3: 2, 6, 18, 54, 162."}, {"id": 11301, "materia": "rl", "nivel": 3, "enunciado": "Sabe-se que \"Se A, então B\" e \"Se B, então C\" são verdadeiras, e que A é verdadeira. Conclui-se que:", "opcoes": ["C é verdadeira", "C é falsa", "B é falsa", "Nada se conclui"], "explicacao": "A leva a B, e B leva a C."}, {"id": 11302, "materia": "rl", "nivel": 4, "enunciado": "Uma prova tem 3 questões de verdadeiro ou falso. Chutando todas, a chance de acertar as três é:", "opcoes": ["1/8", "1/3", "1/6", "3/8"], "explicacao": "Cada uma tem chance 1/2: 1/2 × 1/2 × 1/2 = 1/8."}, {"id": 11303, "materia": "rl", "nivel": 4, "enunciado": "A proposição \"p ou não p\" é sempre verdadeira. Ela é chamada de:", "opcoes": ["Tautologia", "Contradição", "Contingência", "Equivalência"], "explicacao": "Qualquer que seja o valor de p, ela é verdadeira."}, {"id": 11304, "materia": "rl", "nivel": 4, "enunciado": "Maria aplicou R$ 5.000 a juros simples de 2% ao mês. Depois de 4 meses, recebeu de juros:", "opcoes": ["R$ 400", "R$ 100", "R$ 800", "R$ 40"], "explicacao": "5.000 × 0,02 × 4 = 400."}, {"id": 11305, "materia": "rl", "nivel": 4, "enunciado": "Com 5 pessoas, quantas filas diferentes de 3 pessoas podem ser formadas, se a ordem importa?", "opcoes": ["60", "10", "15", "125"], "explicacao": "Arranjo: 5 × 4 × 3 = 60."}, {"id": 11306, "materia": "rl", "nivel": 4, "enunciado": "Num concurso, 40% dos candidatos são homens. Passaram 30% dos homens e 50% das mulheres. Que porcentagem do total passou?", "opcoes": ["42%", "40%", "80%", "35%"], "explicacao": "0,4 × 0,3 + 0,6 × 0,5 = 0,12 + 0,30 = 0,42."}, {"id": 11307, "materia": "inf", "nivel": 0, "enunciado": "O mouse é usado principalmente para:", "opcoes": ["Apontar e clicar na tela", "Imprimir documentos", "Mostrar imagens", "Guardar arquivos"], "explicacao": "É um dispositivo de entrada."}, {"id": 11308, "materia": "inf", "nivel": 0, "enunciado": "Para levar arquivos de um computador para outro, sem internet, pode-se usar um:", "opcoes": ["Pen drive", "Mouse", "Monitor", "Fone de ouvido"], "explicacao": "O pen drive é uma memória portátil."}, {"id": 11309, "materia": "inf", "nivel": 0, "enunciado": "Uma rede Wi-Fi é uma rede:", "opcoes": ["Sem fio", "Só com cabos", "Só de telefone fixo", "Só de televisão"], "explicacao": "Funciona por ondas de rádio."}, {"id": 11310, "materia": "inf", "nivel": 0, "enunciado": "O monitor do computador é um dispositivo de:", "opcoes": ["Saída", "Entrada", "Armazenamento", "Processamento"], "explicacao": "Ele exibe as informações para o usuário."}, {"id": 11311, "materia": "inf", "nivel": 1, "enunciado": "O \"https\" no começo de um endereço indica que a conexão:", "opcoes": ["É criptografada", "É mais lenta", "É gratuita", "Não tem senha"], "explicacao": "O \"s\" indica conexão segura."}, {"id": 11312, "materia": "inf", "nivel": 1, "enunciado": "A memória RAM é chamada de volátil porque:", "opcoes": ["Perde os dados quando o computador desliga", "Guarda arquivos para sempre, mesmo desligado", "Fica fora do computador", "Só funciona na internet"], "explicacao": "Os arquivos ficam salvos no disco (HD ou SSD), não na RAM."}, {"id": 11313, "materia": "inf", "nivel": 1, "enunciado": "1 gigabyte (GB) equivale a, aproximadamente:", "opcoes": ["1.024 megabytes", "100 megabytes", "10 kilobytes", "1 terabyte"], "explicacao": "1 GB = 1.024 MB."}, {"id": 11314, "materia": "inf", "nivel": 1, "enunciado": "Mensagens não solicitadas, enviadas em massa por e-mail, são chamadas de:", "opcoes": ["Spam", "Backup", "Download", "Cookie"], "explicacao": "Muitas vezes trazem propaganda ou golpes."}, {"id": 11315, "materia": "inf", "nivel": 2, "enunciado": "Um golpista ligou fingindo ser do suporte técnico e convenceu a vítima a passar a senha. Essa técnica é a:", "opcoes": ["Engenharia social", "Criptografia", "Compactação", "Formatação"], "explicacao": "Manipulação psicológica para obter informações."}, {"id": 11316, "materia": "inf", "nivel": 2, "enunciado": "No Word, o recurso que aponta erros de ortografia enquanto você digita é a:", "opcoes": ["Verificação ortográfica", "Mala direta", "Quebra de seção", "Marca d'água"], "explicacao": "As palavras com erro ficam sublinhadas em vermelho."}, {"id": 11317, "materia": "inf", "nivel": 2, "enunciado": "A tecnologia Bluetooth serve para:", "opcoes": ["Conectar aparelhos sem fio a curta distância", "Acessar a internet por satélite", "Imprimir em papel especial", "Aumentar a memória interna do celular em uso"], "explicacao": "Usada em fones, caixas de som e teclados."}, {"id": 11318, "materia": "inf", "nivel": 2, "enunciado": "Um software livre, como o Linux, pode ser:", "opcoes": ["Estudado, modificado e distribuído", "Usado só pelo fabricante", "Usado só com licença paga ao fabricante", "Instalado só em celulares"], "explicacao": "São as liberdades do software livre."}, {"id": 11319, "materia": "inf", "nivel": 3, "enunciado": "No Excel, quando aparece ##### numa célula com número, geralmente significa que:", "opcoes": ["A coluna está estreita demais para mostrar o valor", "A fórmula da célula tem um erro de divisão por zero", "O arquivo está corrompido", "O número é negativo"], "explicacao": "Basta alargar a coluna."}, {"id": 11320, "materia": "inf", "nivel": 3, "enunciado": "O endereço IP serve para:", "opcoes": ["Identificar um dispositivo na rede", "Proteger o computador contra vírus", "Guardar senhas do navegador", "Aumentar a velocidade da internet"], "explicacao": "Cada aparelho conectado tem um endereço IP."}, {"id": 11321, "materia": "inf", "nivel": 3, "enunciado": "O DNS é o serviço que:", "opcoes": ["Traduz nomes de sites em endereços IP", "Bloqueia todos os vírus que circulam na rede", "Guarda cópias de segurança", "Cria senhas automaticamente"], "explicacao": "Permite digitar nomes, em vez de números, no navegador."}, {"id": 11322, "materia": "inf", "nivel": 3, "enunciado": "No Excel, =SOMASE(A1:A5;\">10\") soma:", "opcoes": ["Os valores do intervalo maiores que 10", "A quantidade de células maiores que 10", "Todos os valores do intervalo", "Os valores menores que 10"], "explicacao": "SOMASE soma apenas o que atende ao critério."}, {"id": 11323, "materia": "inf", "nivel": 4, "enunciado": "No Excel, =CONT.VALORES(A1:A10) retorna:", "opcoes": ["A quantidade de células não vazias", "A soma dos valores numéricos", "A quantidade de células vazias do intervalo", "O maior valor do intervalo"], "explicacao": "CONT.VALORES conta qualquer conteúdo; CONTAR.VAZIO conta as vazias."}, {"id": 11324, "materia": "inf", "nivel": 4, "enunciado": "No Excel, =CONCATENAR(\"Ana\";\" \";\"Lima\") retorna:", "opcoes": ["Ana Lima", "AnaLima", "Ana;Lima", "#NOME?"], "explicacao": "Junta os textos, incluindo o espaço indicado."}, {"id": 11325, "materia": "inf", "nivel": 4, "enunciado": "No Excel, a referência $A1, copiada para outra coluna e outra linha:", "opcoes": ["Mantém a coluna A e muda a linha", "Mantém a linha 1 e muda a coluna", "Não muda nada", "Muda coluna e linha"], "explicacao": "O cifrão fixa apenas o que vem logo depois dele."}, {"id": 11326, "materia": "inf", "nivel": 4, "enunciado": "Na criptografia simétrica:", "opcoes": ["A mesma chave cifra e decifra", "Usam-se chave pública e chave privada", "Não há nenhuma chave", "A chave é sempre a senha do Wi-Fi"], "explicacao": "Na assimétrica, há um par de chaves."}, {"id": 11327, "materia": "const", "nivel": 0, "enunciado": "No Brasil, a Constituição é a lei:", "opcoes": ["Mais importante do país", "Menos importante do país", "Só dos militares", "Só dos estados"], "explicacao": "Todas as outras leis devem respeitá-la."}, {"id": 11328, "materia": "const", "nivel": 0, "enunciado": "Pela Constituição, os Poderes Legislativo, Executivo e Judiciário são independentes e:", "opcoes": ["Harmônicos entre si", "Subordinados ao Executivo", "Subordinados ao Judiciário", "Iguais aos municípios"], "explicacao": "Art. 2º da Constituição."}, {"id": 11329, "materia": "const", "nivel": 0, "enunciado": "Pela Constituição, o Brasil é uma República:", "opcoes": ["Federativa", "Monárquica", "Parlamentarista", "Unitária"], "explicacao": "Art. 1º: República Federativa do Brasil."}, {"id": 11330, "materia": "const", "nivel": 1, "enunciado": "O direito de pedir algo aos órgãos públicos (direito de petição) é:", "opcoes": ["Gratuito", "Pago", "Só para advogados", "Só para servidores"], "explicacao": "Art. 5º, XXXIV, da Constituição."}, {"id": 11331, "materia": "const", "nivel": 1, "enunciado": "Para conhecer ou corrigir informações sobre você em bancos de dados do governo, usa-se o:", "opcoes": ["Habeas data", "Habeas corpus", "Mandado de injunção", "Ação popular"], "explicacao": "Art. 5º, LXXII, da Constituição."}, {"id": 11332, "materia": "const", "nivel": 1, "enunciado": "O habeas corpus protege a liberdade de:", "opcoes": ["Locomoção", "Imprensa", "Religião", "Associação"], "explicacao": "Art. 5º, LXVIII, da Constituição."}, {"id": 11333, "materia": "const", "nivel": 2, "enunciado": "Lia nasceu na Itália, filha de mãe brasileira, e foi registrada no consulado brasileiro. Ela é:", "opcoes": ["Brasileira nata", "Brasileira naturalizada", "Estrangeira", "Apátrida"], "explicacao": "Art. 12, I, \"c\", da Constituição."}, {"id": 11334, "materia": "const", "nivel": 2, "enunciado": "Pela Constituição, o salário mínimo é:", "opcoes": ["Fixado em lei e nacionalmente unificado", "Diferente em cada estado, por decreto do governador", "Definido por cada empresa", "Fixado pelos sindicatos"], "explicacao": "Art. 7º, IV, da Constituição."}, {"id": 11335, "materia": "const", "nivel": 2, "enunciado": "São direitos sociais previstos no art. 6º da Constituição, entre outros:", "opcoes": ["Educação, saúde e moradia", "Carro, viagem e celular para todos", "Herança e testamento", "Imposto e taxa"], "explicacao": "Também alimentação, trabalho, transporte, lazer, segurança e previdência."}, {"id": 11336, "materia": "const", "nivel": 3, "enunciado": "A ação popular serve para anular ato que prejudique:", "opcoes": ["O patrimônio público ou o meio ambiente", "Só o patrimônio de uma empresa privada qualquer", "Só a honra de uma pessoa", "Só o direito de voto"], "explicacao": "Art. 5º, LXXIII: patrimônio público, moralidade administrativa, meio ambiente e patrimônio histórico e cultural."}, {"id": 11337, "materia": "const", "nivel": 3, "enunciado": "A lei complementar é aprovada por:", "opcoes": ["Maioria absoluta", "Maioria simples", "3/5 em dois turnos", "Unanimidade"], "explicacao": "Art. 69 da Constituição."}, {"id": 11338, "materia": "const", "nivel": 3, "enunciado": "O Senado Federal é formado por quantos senadores?", "opcoes": ["81", "513", "27", "54"], "explicacao": "3 por estado e 3 pelo DF: 27 × 3 = 81."}, {"id": 11339, "materia": "const", "nivel": 4, "enunciado": "O transporte passou a ser direito social pela Emenda Constitucional:", "opcoes": ["90/2015", "45/2004", "19/1998", "26/2000"], "explicacao": "A EC 26/2000 incluiu a moradia."}, {"id": 11340, "materia": "const", "nivel": 4, "enunciado": "A iniciativa de lei que cria cargos na administração federal é privativa do:", "opcoes": ["Presidente da República", "Presidente da Câmara", "Procurador-Geral da República", "Presidente do STF"], "explicacao": "Art. 61, § 1º, II, \"a\", da Constituição."}, {"id": 11341, "materia": "const", "nivel": 4, "enunciado": "A ação direta de inconstitucionalidade (ADI) contra lei federal ou estadual é julgada pelo:", "opcoes": ["STF", "STJ", "TSE", "Tribunal de Justiça"], "explicacao": "Art. 102, I, \"a\", da Constituição."}, {"id": 11342, "materia": "pcd", "nivel": 0, "enunciado": "Rampas de acesso nos prédios ajudam principalmente:", "opcoes": ["Pessoas com mobilidade reduzida", "Só os funcionários do prédio público", "Só os entregadores", "Ninguém"], "explicacao": "São exigência de acessibilidade."}, {"id": 11343, "materia": "pcd", "nivel": 1, "enunciado": "O Braille é um sistema de leitura e escrita para pessoas:", "opcoes": ["Cegas", "Surdas", "Com deficiência física", "Idosas apenas"], "explicacao": "Usa pontos em relevo."}, {"id": 11344, "materia": "pcd", "nivel": 2, "enunciado": "Pela LBI, acessibilidade é a possibilidade de usar espaços, transportes e serviços com:", "opcoes": ["Segurança e autonomia", "Ajuda obrigatória de terceiros", "Pagamento de taxa extra", "Autorização judicial"], "explicacao": "Art. 3º, I, da Lei 13.146/2015."}, {"id": 11345, "materia": "pcd", "nivel": 3, "enunciado": "Pela LBI, desenho universal é a concepção de produtos e ambientes que:", "opcoes": ["Possam ser usados por todos, sem adaptação", "Sejam exclusivos para pessoas com deficiência", "Custem menos para o governo", "Sigam um padrão estrangeiro"], "explicacao": "Art. 3º, II, da Lei 13.146/2015."}, {"id": 11346, "materia": "pcd", "nivel": 4, "enunciado": "Pela LBI, um programa leitor de tela para pessoas cegas é exemplo de:", "opcoes": ["Tecnologia assistiva", "Barreira tecnológica", "Desenho exclusivo", "Adaptação proibida"], "explicacao": "Art. 3º, III, da Lei 13.146/2015."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes where id < 1000000));
select nivel, count(*) as questoes_novas from public.questoes where id between 11247 and 11346 group by nivel order by nivel;
select public.questoes_versao() as nova_versao;
